const context = $('When Executed by Another Workflow').first().json;

function requireObject(value, name) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`${name} must be an object`);
  }
  return value;
}

function requireText(value, name) {
  if (typeof value !== 'string' || value.trim() === '') {
    throw new Error(`${name} must be a non-empty string`);
  }
  return value.trim();
}

function optionalText(value) {
  if (value === undefined || value === null) return null;
  const normalized = String(value).trim();
  return normalized === '' ? null : normalized;
}

function compactProperties(properties) {
  return Object.fromEntries(
    Object.entries(properties).filter(([, value]) => (
      value !== undefined &&
      value !== null &&
      !(typeof value === 'string' && value.trim() === '')
    )),
  );
}

function boundedText(value, fallback, maximumLength = 500) {
  const normalized = optionalText(value) ?? fallback;
  return normalized.slice(0, maximumLength);
}

const lead = requireObject(context.lead, 'lead');
const aiResult = requireObject(context.ai_result, 'ai_result');
const correlationId = requireText(context.correlation_id, 'correlation_id');
const submissionReference =
  optionalText(context.submission_reference) ?? correlationId;
const ai = aiResult.ai_response ?? {};
const decision =
  aiResult.deterministic_decision ??
  aiResult.review_outcome ??
  null;
requireObject(decision, 'ai_result decision');

const isReviewOutcome = Boolean(aiResult.review_outcome);
const finalRoute =
  optionalText(decision.final_route) ??
  (isReviewOutcome ? 'human_review' : null);
const routeReason =
  optionalText(decision.route_reason) ??
  (isReviewOutcome ? 'invalid_ai_response' : 'qualification_completed');

if (!finalRoute) {
  throw new Error('A final qualification route is required');
}

const requestedService = optionalText(lead.service_requested);
const serviceCategory =
  optionalText(ai.service_category) && ai.service_category !== 'unknown'
    ? ai.service_category
    : requestedService ?? 'other';
const companyOrContact =
  optionalText(lead.company) ??
  optionalText(
    [optionalText(lead.first_name), optionalText(lead.last_name)]
      .filter(Boolean)
      .join(' '),
  ) ??
  requireText(lead.email_normalized, 'lead.email_normalized');
const qualificationExplanation = isReviewOutcome
  ? `Human review required: ${routeReason}`
  : boundedText(
    ai.qualification_reason,
    `Qualification completed: ${routeReason}`,
  );
const dealQualificationProperties = compactProperties({
  dealname: `${companyOrContact} - ${serviceCategory}`,
  service_category: serviceCategory,
  lead_score:
    Number.isInteger(decision.final_score)
      ? String(decision.final_score)
      : null,
  qualification_status: finalRoute,
  urgency: optionalText(ai.urgency) ?? 'unknown',
  problem_summary: boundedText(
    ai.problem_summary,
    boundedText(
      lead.message_sanitized,
      'Qualification output requires human review.',
    ),
  ),
  ai_confidence:
    typeof ai.confidence === 'number' ? String(ai.confidence) : '0',
  qualification_explanation: qualificationExplanation,
  workflow_correlation_id: correlationId,
  original_submission_reference: submissionReference,
});

return [{
  json: {
    deal_request: {
      search_request: {
        filterGroups: [{
          filters: [{
            propertyName: 'workflow_correlation_id',
            operator: 'EQ',
            value: correlationId,
          }],
        }],
        properties: [
          'dealname',
          'workflow_correlation_id',
          'original_submission_reference',
        ],
        limit: 2,
      },
      create_properties: {
        ...dealQualificationProperties,
        pipeline: optionalText(context.hubspot_pipeline_id) ?? 'default',
        dealstage:
          optionalText(context.hubspot_dealstage_id) ??
          'appointmentscheduled',
      },
      update_properties: dealQualificationProperties,
    },
    correlation_id: correlationId,
  },
}];

const dealContext = $('Build HubSpot Deal Request').first().json;
const candidates = $input.all()
  .filter((item) => item.json?.id !== undefined && item.json?.id !== null)
  .map((item) => String(item.json.id));

let dealMatch;
if (candidates.length === 0) {
  dealMatch = {
    action: 'create',
    deal_id: null,
    match_count: 0,
    candidate_deal_ids: [],
    review_reason: null,
  };
} else if (candidates.length === 1) {
  dealMatch = {
    action: 'update',
    deal_id: candidates[0],
    match_count: 1,
    candidate_deal_ids: candidates,
    review_reason: null,
  };
} else {
  dealMatch = {
    action: 'review',
    deal_id: null,
    match_count: candidates.length,
    candidate_deal_ids: candidates,
    review_reason: 'multiple_deals_for_correlation_id',
  };
}

return [{
  json: {
    deal_request: dealContext.deal_request,
    deal_match: dealMatch,
    should_write: dealMatch.action !== 'review',
    correlation_id: dealContext.correlation_id,
  },
}];

const context = $('When Executed by Another Workflow').first().json;
const dealDecision = $input.first()?.json ?? {};

function requireObject(value, name) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`${name} must be an object`);
  }
  return value;
}

function requireText(value, name) {
  if (typeof value !== 'string' || value.trim() === '') {
    throw new Error(`${name} must be a non-empty string`);
  }
  return value.trim();
}

function optionalText(value) {
  if (value === undefined || value === null) return null;
  const normalized = String(value).trim();
  return normalized === '' ? null : normalized;
}

function compactProperties(properties) {
  return Object.fromEntries(
    Object.entries(properties).filter(([, value]) => (
      value !== undefined &&
      value !== null &&
      !(typeof value === 'string' && value.trim() === '')
    )),
  );
}

const lead = requireObject(context.lead, 'lead');
const crmMatch = requireObject(context.crm_match, 'crm_match');
const crmAction = requireText(context.crm_action, 'crm_action');
const receivedAt = optionalText(context.received_at) ?? new Date().toISOString();

if (!['create', 'update'].includes(crmAction)) {
  throw new Error(`Unsupported crm_action: ${crmAction}`);
}
if (crmAction === 'update' && !optionalText(crmMatch.contact_id)) {
  throw new Error('crm_match.contact_id is required for a contact update');
}

const contactRequest = {
  action: crmAction,
  write_mode:
    crmAction === 'update' && crmMatch.matched_by !== 'email'
      ? 'update_by_id'
      : 'upsert_by_email',
  contact_id: optionalText(crmMatch.contact_id),
  properties: compactProperties({
    firstname: optionalText(lead.first_name),
    lastname: optionalText(lead.last_name),
    email: requireText(lead.email_normalized, 'lead.email_normalized')
      .toLowerCase(),
    phone: optionalText(lead.phone_normalized),
    company: optionalText(lead.company),
    source: optionalText(context.source) ?? 'portfolio_demo',
    consent_status: String(lead.consent === true),
    consent_timestamp: receivedAt,
    last_enquiry_date: receivedAt,
  }),
};

return [{
  json: {
    contact_request: contactRequest,
    deal_request: dealDecision.deal_request,
    deal_match: dealDecision.deal_match,
    correlation_id: dealDecision.correlation_id,
  },
}];

const requestContext = $('Build HubSpot Contact Request').first().json;
const response = $input.first()?.json ?? {};
const contactId =
  response.id ??
  response.vid ??
  response.properties?.hs_object_id ??
  requestContext.contact_request.contact_id ??
  null;

if (contactId === null || contactId === undefined || String(contactId).trim() === '') {
  throw new Error('HubSpot contact response did not include a contact ID');
}

return [{
  json: {
    contact_request: requestContext.contact_request,
    deal_request: requestContext.deal_request,
    deal_match: requestContext.deal_match,
    correlation_id: requestContext.correlation_id,
    contact_result: {
      action: requestContext.contact_request.action,
      contact_id: String(contactId),
    },
  },
}];

const contactContext = $('Attach Contact Response').first().json;
const response = $input.first()?.json ?? {};
const dealId =
  response.id ??
  response.dealId ??
  response.properties?.hs_object_id ??
  contactContext.deal_match.deal_id ??
  null;

if (dealId === null || dealId === undefined || String(dealId).trim() === '') {
  throw new Error('HubSpot deal response did not include a deal ID');
}

return [{
  json: {
    correlation_id: contactContext.correlation_id,
    contact_result: contactContext.contact_result,
    deal_result: {
      action: contactContext.deal_match.action,
      deal_id: String(dealId),
    },
  },
}];

const writeContext = $('Attach Deal Response').first().json;

return [{
  json: {
    hubspot_write_success: true,
    correlation_id: writeContext.correlation_id,
    contact: writeContext.contact_result,
    deal: {
      ...writeContext.deal_result,
      associated_contact_id: writeContext.contact_result.contact_id,
    },
  },
}];

const decision = $input.first()?.json ?? {};

return [{
  json: {
    hubspot_write_success: false,
    correlation_id: decision.correlation_id ?? null,
    contact: null,
    deal: {
      action: 'review',
      deal_id: null,
      candidate_deal_ids:
        decision.deal_match?.candidate_deal_ids ?? [],
      review_reason:
        decision.deal_match?.review_reason ??
        'ambiguous_deal_match',
    },
  },
}];
